mapper.select:
select aaa.* from (
UNION ALL
) aaa left join SYS_DATADICT_LIST sdl on aaa.entrustStatus=sdl.ITEM_CODE and sdl.DICT_CODE='ENTRUST_STATUS' order by sdl.ORDER_NO, aaa.entrustId DESC

mapper.sql:
SELECT T1.ENTRUST_ID entrustId, T1.FINPROD_ID finprodId, T1.ENTRUST_STATUS entrustStatus, T1.INV_MANAGER_ID invManagerId, T1.PORTFOLIO_ID portfolioId, T2.PORTFOLIO_NAME portfolioName, T3.FINPROD_MARKET_ID finprodMarketId, T3.FINPROD_ABBR finprodAbbr, T1.ENTRUST_DATE entrustDate, T6.PURCH_MODLE purchModle, T1.ENTRUST_NUM entrustNum, T1.PRICE price, T1.ENTRUST_AMT entrustAmt, T1.CCY ccy, T1.REMARK remark FROM WFL_ETR_ENTRUST T1 LEFT JOIN PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID INNER JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY T5 ON T2.PORTFOLIO_ID = T5.PORTFOLIO_ID INNER JOIN WFL_ETR_ENTRUST_ADD T6 ON T1.ENTRUST_ID = T6.ENTRUST_ID
AND T5.USER_ID = #{userId,jdbcType=VARCHAR} AND T1.FINPROD_TYPE2 = 'F10' AND T1.PS = 'T04' AND T1.ENTRUST_STATUS = '09'
AND (T2.PORTFOLIO_ID IN
#{prot}
or T2.PARENT_PORTFOLIO_ID IN
#{prot}
)
AND (T3.FINPROD_MARKET_ID like concat('%',concat(#{finprodId,jdbcType=VARCHAR},'%')) OR T3.FINPROD_ABBR like concat('%',concat(#{finprodId,jdbcType=VARCHAR},'%')))
AND T1.TRADE_MARKET=#{tradeMarket,jdbcType=VARCHAR}
AND T6.PURCH_MODLE=#{purchModle,jdbcType=VARCHAR}
AND T1.VDATE >=to_date(#{startDate},'yyyy-MM-dd')
AND T1.MDATE <=to_date(#{endDate},'yyyy-MM-dd')

SELECT T1.ENTRUST_ID entrustId, T1.FINPROD_ID finprodId, T1.ENTRUST_STATUS entrustStatus, T1.INV_MANAGER_ID invManagerId, T1.PORTFOLIO_ID portfolioId, T2.PORTFOLIO_NAME portfolioName, T3.FINPROD_MARKET_ID finprodMarketId, T3.FINPROD_ABBR finprodAbbr, T1.ENTRUST_DATE entrustDate, T6.PURCH_MODLE purchModle, T1.ENTRUST_NUM entrustNum, T1.PRICE price, T1.ENTRUST_AMT entrustAmt, T1.CCY ccy, T1.REMARK remark FROM ETR_ENTRUST T1 LEFT JOIN PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID INNER JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY T5 ON T2.PORTFOLIO_ID = T5.PORTFOLIO_ID INNER JOIN ETR_ENTRUST_ADD T6 ON T1.ENTRUST_ID = T6.ENTRUST_ID
AND T1.FINPROD_TYPE2 = 'F10' AND T1.PS = 'T04' AND T5.USER_ID = #{userId,jdbcType=VARCHAR}
AND (T2.PORTFOLIO_ID IN
#{prot}
or T2.PARENT_PORTFOLIO_ID IN
#{prot}
)
AND (T3.FINPROD_MARKET_ID like concat('%',concat(#{finprodId,jdbcType=VARCHAR},'%')) OR T3.FINPROD_ABBR like concat('%',concat(#{finprodId,jdbcType=VARCHAR},'%')))
AND T1.TRADE_MARKET=#{tradeMarket,jdbcType=VARCHAR}
AND T6.PURCH_MODLE=#{purchModle,jdbcType=VARCHAR}
AND T1.ENTRUST_STATUS = #{entrustStatus,jdbcType=VARCHAR}
AND T1.VDATE >=to_date(#{startDate},'yyyy-MM-dd')
AND T1.MDATE <=to_date(#{endDate},'yyyy-MM-dd')

mapper.select:
SELECT FINPROD_MARKET_ID code, FINPROD_MARKET_ID name, FINPROD_NAME shortName, FINPROD_ID hidCode FROM FIN_PRODUCT
FINPROD_MARKET_ID IS NOT NULL AND FINPROD_TYPE2 = #{planasset}
and (FINPROD_MARKET_ID like concat('%',concat(#{param},'%')) or FINPROD_NAME like concat('%',concat(#{param},'%')))

SELECT T1.PORTFOLIO_ID id, T1.PORTFOLIO_NAME text FROM PTL_PORTFOLIO T1 INNER JOIN PTL_PORTFOLIO_AUTHORITY T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID AND T2.USER_ID = #{userId}
and T1.PORTFOLIO_ID = #{initValue}
and (T1.PORTFOLIO_ID like concat('%',concat(#{search},'%')) or T1.PORTFOLIO_NAME like concat('%',concat(#{search},'%')))

SELECT T1.FINPROD_MARKET_ID id, T1.FINPROD_NAME text, T1.FINPROD_ID, T1.CALENDAR_ID, T1.CCY, T2.BOARD, T1.TRADE_MARKET, T1.VDATE, T1.MDATE FROM FIN_PRODUCT T1 LEFT JOIN FIN_PRODUCT_ADD T2 ON T1.FINPROD_ID = T2.FINPROD_ID
T1.FINPROD_MARKET_ID IS NOT NULL AND T1.FINPROD_TYPE2 = #{planasset}
and (T1.FINPROD_MARKET_ID like concat('%',concat(#{search},'%')) or T1.FINPROD_NAME like concat('%',concat(#{search},'%')))
and T1.FINPROD_MARKET_ID = #{initValue}

		select
			T.FINPROD_ID       id,
			T.FINPROD_NAME     text
		from FIN_PRODUCT T


             AND T.FINPROD_TYPE2 = #{finprodType2}


              AND T.IS_CHL = #{isChl}

select
  AMOUNT
from PTL_CASH_POSITION
where
	(HODING_TYPE=#{POSITION_TYPE_01} or HODING_TYPE=#{POSITION_TYPE_03}) and PORTFOLIO_ID=#{portfolioId}
	and CDATE=(select cur_date from sys_date) and CHL_FINPROD_ID=#{TongDao}

SELECT T1.ENTRUST_ID entrustId, T1.PORTFOLIO_ID portfolioId, T1.VDATE vdate, T1.MDATE mdate, T6.TYPE_6 assetType1, T6.TYPE_7 assetType2, T1.CCY ccy, T3.FINPROD_MARKET_ID finprodMarketId, T3.FINPROD_NAME finprodName, T1.PS ps, T1.PRICE price, T1.PRICE_MODEL priceModel, T1.TRADE_MARKET tradeMarket, T4.BOARD board, T5.DEAL_MODE dealMode, T5.SEC_ACCT_ID secAcctId, T1.ENTRUST_AMT entrustAmt, T1.ENTRUST_NUM entrustNum, T1.PRO_AVAILABLE_CASH proAvailableCash, T1.ACC_AVAILABLE_CASH accAvailableCash, T1.REMARK remark, T1.COUNTER_ID counterId, T1.COUNTER_TRADER counterTrader, T1.CONTACT_INFO contactInfo, T2.TRADER trader, T1.INV_MANAGER_ID invManagerId, T1.CHL_ID chlId, T1.SALE_CODE saleCode, T1.ENTRUST_DATE entrustDate, T5.PURCH_MODLE purchModle FROM ETR_ENTRUST T1 LEFT JOIN ETR_DISTRIBUTE T2 ON T1.ENTRUST_ID = T2.ENTRUST_ID LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID INNER JOIN FIN_PRODUCT_ADD T4 ON T1.FINPROD_ID = T4.FINPROD_ID INNER JOIN ETR_ENTRUST_ADD T5 ON T1.ENTRUST_ID = T5.ENTRUST_ID LEFT JOIN FIN_PRODUCT_TYPE T6 ON T1.FINPROD_ID = T6.FINPROD_ID
T1.ENTRUST_ID = #{entrustId}
union all SELECT T1.ENTRUST_ID entrustId, T1.PORTFOLIO_ID portfolioId, T1.VDATE vdate, T1.MDATE mdate, T6.TYPE_6 assetType1, T6.TYPE_7 assetType2, T1.CCY ccy, T3.FINPROD_MARKET_ID finprodMarketId, T3.FINPROD_NAME finprodName, T1.PS ps, T1.PRICE price, T1.PRICE_MODEL priceModel, T1.TRADE_MARKET tradeMarket, T4.BOARD board, T5.DEAL_MODE dealMode, T5.SEC_ACCT_ID secAcctId, T1.ENTRUST_AMT entrustAmt, T1.ENTRUST_NUM entrustNum, T1.PRO_AVAILABLE_CASH proAvailableCash, T1.ACC_AVAILABLE_CASH accAvailableCash, T1.REMARK remark, T1.COUNTER_ID counterId, T1.COUNTER_TRADER counterTrader, T1.CONTACT_INFO contactInfo, T2.TRADER trader, T1.INV_MANAGER_ID invManagerId, T1.CHL_ID chlId, T1.SALE_CODE saleCode, T1.ENTRUST_DATE entrustDate, T5.PURCH_MODLE purchModle FROM WFL_ETR_ENTRUST T1 LEFT JOIN ETR_DISTRIBUTE T2 ON T1.ENTRUST_ID = T2.ENTRUST_ID LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID INNER JOIN FIN_PRODUCT_ADD T4 ON T1.FINPROD_ID = T4.FINPROD_ID INNER JOIN WFL_ETR_ENTRUST_ADD T5 ON T1.ENTRUST_ID = T5.ENTRUST_ID LEFT JOIN FIN_PRODUCT_TYPE T6 ON T1.FINPROD_ID = T6.FINPROD_ID
T1.ENTRUST_ID = #{entrustId}

SELECT A.ACCT_NO hidCode, A.ACCT_NO code, B.SEC_ACCT_NAME name, B.SEC_ACCT_NAME shortName FROM PTL_SEC_ACCT A INNER JOIN STL_SEC_ACCT_INFO B ON A.ACCT_NO = B.SEC_ACCT_ID
PORTFOLIO_ID = #{portfolioId}
AND ( A.ACCT_NO LIKE CONCAT('%', CONCAT(#{search}, '%')) OR B.SEC_ACCT_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND A.ACCT_NO = #{initValue}
AND B.TRADE_PLACE = #{tradeMarket}
